    data:{ "сырые.csv": "ученик,предмет,балл\n  Аня ,математика,5\nборя,математика,3\n,математика,4\nвика,МАТЕМАТИКА, 4 \nаня,русский,пять\nборя,русский,5\nвика,русский,5\nаня,история,5\nборя,история,\nборя,история,4\n" },
    starter:'import csv\n\n\ndef почистить(строки):\n    """Убирает мусор: пустые имена, лишние пробелы, нечисловые баллы."""\n    чистые = []\n    for строка in строки:\n        чистые.append(строка)\n    return чистые\n\n\nwith open("сырые.csv", encoding="utf-8", newline="") as f:\n    сырые = list(csv.DictReader(f))\n\nчистые = почистить(сырые)\nprint("было строк:", len(сырые))\n',
    solution:'import csv\n\n\ndef почистить(строки):\n    """Убирает мусор: пустые имена, лишние пробелы, нечисловые баллы."""\n    чистые = []\n    for строка in строки:\n        имя = строка["ученик"].strip().lower()\n        предмет = строка["предмет"].strip().lower()\n        балл = строка["балл"].strip()\n        if not имя or not предмет:\n            continue\n        if not балл.isdigit():\n            continue\n        чистые.append({"ученик": имя, "предмет": предмет, "балл": int(балл)})\n    return чистые\n\n\nwith open("сырые.csv", encoding="utf-8", newline="") as f:\n    сырые = list(csv.DictReader(f))\n\nчистые = почистить(сырые)\nprint("было строк:", len(сырые))\nprint("стало строк:", len(чистые))\nprint("выброшено:", len(сырые) - len(чистые))\nfor строка in чистые[:4]:\n    print(строка)\n',
