      show:'import matplotlib.pyplot as plt\n\nданные = {"история": 4.5, "математика": 4.0, "русский": 4.67}\nplt.barh(list(данные), list(данные.values()))\nplt.xlabel("средний балл")\nplt.savefig("оценки.png")',
