    starter:'СТРАНИЦЫ = {}\n\n\ndef маршрут(путь):\n    """Вешает функцию на адрес: теперь по этому пути сервер вызовет её."""\n    def обёртка(функция):\n        return функция\n    return обёртка\n\n\n@маршрут("/про-нас")\ndef про_нас():\n    return "<h1>Про нас</h1><p>Тут учат Python.</p>"\n\n\ndef показать(путь):\n    """Отдаёт страницу по адресу или сообщение, что её нет."""\n    return "404 " + путь\n\n\nprint("адреса:", sorted(СТРАНИЦЫ))\nprint("/", "->", показать("/"))\n',
    solution:'СТРАНИЦЫ = {}\n\n\ndef маршрут(путь):\n    """Вешает функцию на адрес: теперь по этому пути сервер вызовет её."""\n    def обёртка(функция):\n        СТРАНИЦЫ[путь] = функция\n        return функция\n    return обёртка\n\n\n@маршрут("/про-нас")\ndef про_нас():\n    return "<h1>Про нас</h1><p>Тут учат Python.</p>"\n\n\n@маршрут("/")\ndef главная():\n    return "<h1>Кодоквест</h1><p>Первая страница.</p>"\n\n\ndef показать(путь):\n    """Отдаёт страницу по адресу или сообщение, что её нет."""\n    if путь not in СТРАНИЦЫ:\n        return "404 " + путь\n    return СТРАНИЦЫ[путь]()\n\n\nprint("адреса:", sorted(СТРАНИЦЫ))\nfor путь in ["/", "/про-нас", "/склад"]:\n    print(путь, "->", показать(путь))\n',
